from tslearn.bases import BaseModelPackage

class DummyEstimator(BaseModelPackage):
    def __init__(self, alpha=1.0):
        self.alpha = alpha

    def get_params(self, deep=True):
        return {"alpha": self.alpha}

    def _is_fitted(self):
        return hasattr(self, "coef_")

model = DummyEstimator(alpha=2.0)
model.coef_ = [1, 2, 3]

pkg_dict = model._to_dict()

assert pkg_dict["hyper_params"]["alpha"] == 2.0, "Hyperparameters not correctly extracted"
assert pkg_dict["model_params"]["coef_"] == [1, 2, 3], "Model parameters not correctly extracted"
print(f"__CHECK__ BaseModelPackage {pkg_dict['hyper_params']['alpha']} {pkg_dict['model_params']['coef_']}")
